// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e18Be2A7cE626B33C539919EAca06303f1Db568;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.store in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Calculate owner storage slot
        // In Ownable contract: address private _owner; is the first variable
        // So it's at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));

        // Step 2: Overwrite owner with our address
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Step 3: Call setSwapAndLiquifyEnabled(false) as the new owner
        vm.prank(attacker);
        (bool success, ) = TARGET.call(abi.encodeWithSignature("setSwapAndLiquifyEnabled(bool)", false));
        require(success, "Call failed");

        // Step 4: Verify the state was changed
        // Read the swapAndLiquifyEnabled value from storage
        // Need to find its storage slot
        // Looking at the contract: bool public swapAndLiquifyEnabled = true;
        // It's after: IUniswapV2Router02 public immutable uniswapV2Router;
        // address public immutable uniswapV2Pair;
        // bool inSwapAndLiquify;
        // So it's the 4th variable after immutable ones
        // Immutable variables don't use storage, so we need to count properly
        // Let's read using staticcall to the getter
        (, bytes memory data) = TARGET.staticcall(abi.encodeWithSignature("swapAndLiquifyEnabled()"));
        bool enabled = abi.decode(data, (bool));
        assertEq(enabled, false, "swapAndLiquifyEnabled should be false");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
